using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;
namespace Staybnb.Models;
public enum WorkflowStatus { Pending, Approved, Rejected, CheckedIn, Submitted, Verified, NeedsCorrection }
public class HostProperty {
 public int Id {get;set;} public string UserId {get;set;} = ""; public ApplicationUser? User {get;set;}
 [Required, StringLength(120)] public string Title {get;set;} = ""; [Required, StringLength(3000)] public string Description {get;set;} = "";
 [Range(1,10000000)] public decimal PricePerNight {get;set;} [Range(0,1000000)] public decimal CleaningFee {get;set;} [Range(0,1000000)] public decimal ServiceFee {get;set;}
 [Range(1,50)] public int Capacity {get;set;} = 2; [Required, StringLength(200)] public string Address {get;set;} = "";
 [Required, StringLength(80)] public string City {get;set;} = ""; [Required, StringLength(60)] public string PropertyType {get;set;} = "Apartment";
 public bool IsActive {get;set;} public DateTime CreatedAt {get;set;}=DateTime.UtcNow;
 public ICollection<PropertyImage> Images {get;set;}=new List<PropertyImage>(); public ICollection<Booking> Bookings {get;set;}=new List<Booking>();
 public HostApplication? HostApplication {get;set;} public CheckInProcess? CheckInProcess {get;set;} public ICollection<WishlistItem> WishlistItems {get;set;}=new List<WishlistItem>();
 public ICollection<Review> Reviews {get;set;}=new List<Review>(); public ICollection<PropertyAmenity> PropertyAmenities {get;set;}=new List<PropertyAmenity>();
}
public class PropertyImage { public int Id{get;set;} public int PropertyId{get;set;} public HostProperty? Property{get;set;} [Required] public string ImageUrl{get;set;}=""; public bool IsPrimary{get;set;} }
public class HostApplication { public int Id{get;set;} public string ApplicationUserId{get;set;}=""; public ApplicationUser? Applicant{get;set;} public int PropertyId{get;set;} public HostProperty? Property{get;set;} public WorkflowStatus Status{get;set;}=WorkflowStatus.Pending; public DateTime AppliedAt{get;set;}=DateTime.UtcNow; public DateTime? ReviewedAt{get;set;} public string? ReviewNote{get;set;} public string? ReviewedById{get;set;} }
public class Booking { public int Id{get;set;} public int PropertyId{get;set;} public HostProperty? Property{get;set;} public string GuestId{get;set;}=""; public ApplicationUser? Guest{get;set;} public DateTime CheckInDate{get;set;} public DateTime CheckOutDate{get;set;} public int NumberOfGuests{get;set;} public decimal PricePerNightAtBooking{get;set;} public decimal AccommodationSubtotal{get;set;} public decimal CleaningFeeAtBooking{get;set;} public decimal ServiceFeeAtBooking{get;set;} public decimal TotalPrice{get;set;} public WorkflowStatus Status{get;set;}=WorkflowStatus.Pending; public DateTime CreatedAt{get;set;}=DateTime.UtcNow; public Payment? Payment{get;set;} public GuestCheckin? GuestCheckin{get;set;} }
public class Payment { public int Id{get;set;} public int BookingId{get;set;} public Booking? Booking{get;set;} public decimal Amount{get;set;} [StringLength(40)] public string Status{get;set;}="NotProcessed"; public DateTime CreatedAt{get;set;}=DateTime.UtcNow; }
public class Review { public int Id{get;set;} public int PropertyId{get;set;} public HostProperty? Property{get;set;} public string ReviewerId{get;set;}=""; public ApplicationUser? Reviewer{get;set;} [Range(1,5)] public int Rating{get;set;} [StringLength(2000)] public string? Comment{get;set;} public DateTime CreatedAt{get;set;}=DateTime.UtcNow; }
public class Amenity { public int Id{get;set;} [Required, StringLength(80)] public string Name{get;set;}=""; public string? IconClass{get;set;} public ICollection<PropertyAmenity> PropertyAmenities{get;set;}=new List<PropertyAmenity>(); }
public class PropertyAmenity { public int PropertyId{get;set;} public HostProperty? Property{get;set;} public int AmenityId{get;set;} public Amenity? Amenity{get;set;} }
public class WishlistItem { public int Id{get;set;} public string UserId{get;set;}=""; public ApplicationUser? User{get;set;} public int PropertyId{get;set;} public HostProperty? Property{get;set;} public DateTime CreatedAt{get;set;}=DateTime.UtcNow; }
public class Message { public int Id{get;set;} public string SenderId{get;set;}=""; public ApplicationUser? Sender{get;set;} public string ReceiverId{get;set;}=""; public ApplicationUser? Receiver{get;set;} [Required, StringLength(4000)] public string Content{get;set;}=""; public DateTime SentAt{get;set;}=DateTime.UtcNow; public bool IsRead{get;set;} }
public class ActivityLog { public int Id{get;set;} public string? UserId{get;set;} public ApplicationUser? User{get;set;} [Required, StringLength(160)] public string Action{get;set;}=""; [Required, StringLength(60)] public string ActivityType{get;set;}="General"; public DateTime CreatedAt{get;set;}=DateTime.UtcNow; public string? Details{get;set;} }
public class Notification { public int Id{get;set;} public string UserId{get;set;}=""; public ApplicationUser? User{get;set;} [Required, StringLength(160)] public string Title{get;set;}=""; [Required, StringLength(60)] public string Type{get;set;}="General"; public string? LinkUrl{get;set;} public DateTime CreatedAt{get;set;}=DateTime.UtcNow; public bool IsRead{get;set;} }
public class CheckInProcess { public int Id{get;set;} public int PropertyId{get;set;} public HostProperty? Property{get;set;} [Required, StringLength(120)] public string Title{get;set;}="Guest check-in"; [Required] public string StepsJson{get;set;}="[\"Review instructions\",\"Upload required document\"]"; public string RequiredDocumentsJson{get;set;}="[\"ID or passport\"]"; public DateTime CreatedAt{get;set;}=DateTime.UtcNow; }
public class GuestCheckin { public int Id{get;set;} public int BookingId{get;set;} public Booking? Booking{get;set;} public int CheckInProcessId{get;set;} public CheckInProcess? CheckInProcess{get;set;} public WorkflowStatus Status{get;set;}=WorkflowStatus.Pending; public DateTime CreatedAt{get;set;}=DateTime.UtcNow; public ICollection<GuestDocument> Documents{get;set;}=new List<GuestDocument>(); }
public class GuestDocument { public int Id{get;set;} public int GuestCheckinId{get;set;} public GuestCheckin? GuestCheckin{get;set;} [Required, StringLength(60)] public string DocumentType{get;set;}="ID or passport"; [Required, StringLength(255)] public string FileName{get;set;}=""; public WorkflowStatus Status{get;set;}=WorkflowStatus.Submitted; public DateTime UploadedAt{get;set;}=DateTime.UtcNow; public string? ReviewedById{get;set;} public DateTime? ReviewedAt{get;set;} }
